INSERT INTO public.role_family_roles ("id", "role_family_domain_id", "role_id", "description", "observable_behaviours", "role_work_context", "typical_work_activities", "role_output_evidence", "primary_riasec", "secondary_riasec", "tertiary_riasec", "riasec_reason", "degree_gate", "direct_degree_mapping", "riasec_code_string", "aptitude_profile", "big_five_profile", "work_values_profile", "aptitude_assessment", "big5_assessment", "work_values_assessment") VALUES ('74b3a98a-aa65-58a7-ab3d-f763855f2ec1', (SELECT f.id FROM public.role_family_domains f WHERE f.role_family_id=(SELECT id FROM public.role_families WHERE code='WAT_RF01' OR name='Water Quality Analyst' ORDER BY (code='WAT_RF01') DESC LIMIT 1) AND f.industry_domain_id=(SELECT x.id FROM public.industry_domains x WHERE x.industry_id=(SELECT id FROM public.industries WHERE code='IND_WAT_001' OR name='Water & Environmental Services' ORDER BY (code='IND_WAT_001') DESC LIMIT 1) AND x.domain_id=(SELECT id FROM public.domains WHERE code='WAT_D01' OR name='Water Quality & Laboratory Science' ORDER BY (code='WAT_D01') DESC LIMIT 1))), (SELECT id FROM public.role WHERE code='RMR-ROLE-01' OR name='Water Quality Tester' ORDER BY (code='RMR-ROLE-01') DESC LIMIT 1), 'Tests water samples, accurately records results, checks contradictory readings and identifies further safety tests. Future role: Water Quality Analyst; this school course is career exploration, not a professional qualification.', 'Test the Three Coded Liquids: keep cup IDs separate; compare each recorded strip before and after testing; enter the colour observation without assuming the category; Investigate the Cup B Conflict: retain T1 and T2; record a clean-tool fresh-strip T3 separately; compare all three and flag the unexplained T2 conditions; Compare Teacher-Prepared Reference Liquids: match each strip to its own sample, compare observed colours with the correct kit chart and record the classification; Interpret the Fictional R-26 Report: keep pH beside each sample ID; classify A near-neutral, B acidic and C basic; identify untested safety indicators', 'A water-testing laboratory receives labelled samples and must report reliable observations before further safety decisions. Students only investigate prepared school examples.', 'Check cup and sample IDs before testing; Observe red and blue litmus before and after contact; Keep Cup B conflicting tests and document a separately controlled retest; Compare reference-liquid results against a kit-specific chart; Interpret reported R-26 pH while noting missing tests', 'Coded-liquid indicator observation table; Cup B T1/T2/T3 discrepancy log; Reference-liquid comparison sheet; R-26 reported pH and missing-evidence note; Learning modules: RMR-CAP-L02-M01 - Test the Three Coded Liquids (Core, step 1), RMR-CAP-L02-M02 - Investigate the Cup B Conflict (Important, step 2), RMR-CAP-L05-M01 - Compare Teacher-Prepared Reference Liquids (Important, step 3), RMR-CAP-L05-M04 - Interpret the Fictional R-26 Report (Supporting, step 4)', 'I', 'C', 'R', 'Investigative work leads because the tester compares evidence and resolves uncertainty; Conventional methods keep sample IDs and readings accurate; Realistic work involves safely handling basic test apparatus.', 'Preferred', 'B.Sc. Chemistry; B.Sc. Environmental Science; B.Sc. Microbiology; Diploma in Chemical Engineering', 'ICR', '{"verbal_reasoning": 74, "logical_reasoning": 83, "numerical_reasoning": 75, "data_interpretation": 88, "pattern_recognition": 72, "spatial_reasoning": 52}'::jsonb, '{"openness": 4, "conscientiousness": 5, "extraversion": 2, "agreeableness": 3, "emotional_stability": 4}'::jsonb, '{"impact": 5, "status": 3, "autonomy": 3, "security": 4, "financial": 3, "lifestyle": 3, "creativity": 3, "leadership": 2}'::jsonb, '{"areas": ["Data Interpretation", "Logical Reasoning", "Numerical Reasoning"], "rationale": "Water Quality Tester uses data interpretation, logical reasoning, numerical reasoning to check cup and sample ids before testing, observe red and blue litmus before and after contact, and interpret source-based records. These priorities are proposed role demands, not measured learner aptitude."}'::jsonb, '{"traits": ["Conscientiousness", "Openness", "Emotional Stability"], "rationale": "Water Quality Tester benefits from conscientiousness, openness, emotional stability when performing observe red and blue litmus before and after contact and following through on r-26 reported ph and missing-evidence note. Traits guide supportive coaching, not exclusion."}'::jsonb, '{"values": ["Impact", "Security", "Autonomy"], "rationale": "This pathway may reward impact, security, autonomy through the work of check cup and sample ids before testing and producing a clear coded-liquid indicator observation table. These are possible work priorities, not salary or job guarantees."}'::jsonb) ON CONFLICT (id) DO UPDATE SET "role_family_domain_id"=EXCLUDED."role_family_domain_id", "role_id"=EXCLUDED."role_id", "description"=EXCLUDED."description", "observable_behaviours"=EXCLUDED."observable_behaviours", "role_work_context"=EXCLUDED."role_work_context", "typical_work_activities"=EXCLUDED."typical_work_activities", "role_output_evidence"=EXCLUDED."role_output_evidence", "primary_riasec"=EXCLUDED."primary_riasec", "secondary_riasec"=EXCLUDED."secondary_riasec", "tertiary_riasec"=EXCLUDED."tertiary_riasec", "riasec_reason"=EXCLUDED."riasec_reason", "degree_gate"=EXCLUDED."degree_gate", "direct_degree_mapping"=EXCLUDED."direct_degree_mapping", "riasec_code_string"=EXCLUDED."riasec_code_string", "aptitude_profile"=EXCLUDED."aptitude_profile", "big_five_profile"=EXCLUDED."big_five_profile", "work_values_profile"=EXCLUDED."work_values_profile", "aptitude_assessment"=EXCLUDED."aptitude_assessment", "big5_assessment"=EXCLUDED."big5_assessment", "work_values_assessment"=EXCLUDED."work_values_assessment";
