INSERT INTO public.role_family_roles ("id", "role_family_domain_id", "role_id", "description", "observable_behaviours", "role_work_context", "typical_work_activities", "role_output_evidence", "primary_riasec", "secondary_riasec", "tertiary_riasec", "riasec_reason", "degree_gate", "direct_degree_mapping", "riasec_code_string", "aptitude_profile", "big_five_profile", "work_values_profile", "aptitude_assessment", "big5_assessment", "work_values_assessment") VALUES ('0a4a40e3-c92e-5153-86d8-c05676b5d81e', (SELECT f.id FROM public.role_family_domains f WHERE f.role_family_id=(SELECT id FROM public.role_families WHERE code='WAT_RF07' OR name='Water Infrastructure Project Manager' ORDER BY (code='WAT_RF07') DESC LIMIT 1) AND f.industry_domain_id=(SELECT x.id FROM public.industry_domains x WHERE x.industry_id=(SELECT id FROM public.industries WHERE code='IND_WAT_001' OR name='Water & Environmental Services' ORDER BY (code='IND_WAT_001') DESC LIMIT 1) AND x.domain_id=(SELECT id FROM public.domains WHERE code='WAT_D07' OR name='Water Operations & Planning' ORDER BY (code='WAT_D07') DESC LIMIT 1))), (SELECT id FROM public.role WHERE code='RMR-ROLE-07' OR name='Water Project Manager' ORDER BY (code='RMR-ROLE-07') DESC LIMIT 1), 'Plans water-related work, organises budgets and prepares clear evidence-based handovers. Future role: Water Infrastructure Project Manager; the school exercises introduce planning only.', 'Prepare the School-Tank Evidence Note: use the supported volume and observation records; distinguish what separation shows from what drinking-water safety would require; prepare a short note; Finish the Cost and Finding Log: multiply number of strips by unit cost, subtract expenditure from the budget, and write what the test evidence supports; Write a Fair Field-Study Proposal: specify the research question, matched variables, measurements and evidence needed; state where conclusions remain limited; Prepare the Water-Authority Handover: summarise verified observations, missing measurements, limits and the responsible next testing or referral action', 'A local water-project team must plan evidence collection, track small budgets and prepare decisions for responsible managers or authorities.', 'Prepare a school-tank evidence note distinguishing treatment appearance from safety; Calculate indicator-strip spending and available balance; Specify a fair field-study plan with clear controls; Write a water-authority handover with next action and owner', 'School-tank evidence note; Strip-cost and balance log; Field-study proposal; Water-authority handover and responsibility record; Learning modules: RMR-CAP-L01-M04 - Prepare the School-Tank Evidence Note (Core, step 1), RMR-CAP-L02-M04 - Finish the Cost and Finding Log (Important, step 2), RMR-CAP-L03-M04 - Write a Fair Field-Study Proposal (Important, step 3), RMR-CAP-L05-M05 - Prepare the Water-Authority Handover (Supporting, step 4)', 'E', 'C', 'S', 'Enterprising work coordinates tasks and decisions; Conventional practice tracks costs and deliverables; Social work communicates responsibilities across people and authorities.', 'Preferred', 'B.Tech. Civil Engineering; B.Tech. Environmental Engineering; Bachelor of Business Administration (BBA); Master of Business Administration (MBA)', 'ECS', '{"verbal_reasoning": 91, "logical_reasoning": 82, "numerical_reasoning": 84, "data_interpretation": 88, "pattern_recognition": 70, "spatial_reasoning": 63}'::jsonb, '{"openness": 4, "conscientiousness": 5, "extraversion": 5, "agreeableness": 4, "emotional_stability": 4}'::jsonb, '{"impact": 5, "status": 4, "autonomy": 4, "security": 4, "financial": 4, "lifestyle": 3, "creativity": 4, "leadership": 5}'::jsonb, '{"areas": ["Verbal Reasoning", "Data Interpretation", "Numerical Reasoning"], "rationale": "Water Project Manager uses verbal reasoning, data interpretation, numerical reasoning to prepare a school-tank evidence note distinguishing treatment appearance from safety, calculate indicator-strip spending and available balance, and interpret source-based records. These priorities are proposed role demands, not measured learner aptitude."}'::jsonb, '{"traits": ["Conscientiousness", "Extraversion", "Agreeableness"], "rationale": "Water Project Manager benefits from conscientiousness, extraversion, agreeableness when performing calculate indicator-strip spending and available balance and following through on water-authority handover and responsibility record. Traits guide supportive coaching, not exclusion."}'::jsonb, '{"values": ["Impact", "Leadership", "Autonomy"], "rationale": "This pathway may reward impact, leadership, autonomy through the work of prepare a school-tank evidence note distinguishing treatment appearance from safety and producing a clear school-tank evidence note. These are possible work priorities, not salary or job guarantees."}'::jsonb) ON CONFLICT (id) DO UPDATE SET "role_family_domain_id"=EXCLUDED."role_family_domain_id", "role_id"=EXCLUDED."role_id", "description"=EXCLUDED."description", "observable_behaviours"=EXCLUDED."observable_behaviours", "role_work_context"=EXCLUDED."role_work_context", "typical_work_activities"=EXCLUDED."typical_work_activities", "role_output_evidence"=EXCLUDED."role_output_evidence", "primary_riasec"=EXCLUDED."primary_riasec", "secondary_riasec"=EXCLUDED."secondary_riasec", "tertiary_riasec"=EXCLUDED."tertiary_riasec", "riasec_reason"=EXCLUDED."riasec_reason", "degree_gate"=EXCLUDED."degree_gate", "direct_degree_mapping"=EXCLUDED."direct_degree_mapping", "riasec_code_string"=EXCLUDED."riasec_code_string", "aptitude_profile"=EXCLUDED."aptitude_profile", "big_five_profile"=EXCLUDED."big_five_profile", "work_values_profile"=EXCLUDED."work_values_profile", "aptitude_assessment"=EXCLUDED."aptitude_assessment", "big5_assessment"=EXCLUDED."big5_assessment", "work_values_assessment"=EXCLUDED."work_values_assessment";
