INSERT INTO public.role_family_roles ("id", "role_family_domain_id", "role_id", "description", "observable_behaviours", "role_work_context", "typical_work_activities", "role_output_evidence", "primary_riasec", "secondary_riasec", "tertiary_riasec", "riasec_reason", "degree_gate", "direct_degree_mapping", "riasec_code_string", "aptitude_profile", "big_five_profile", "work_values_profile", "aptitude_assessment", "big5_assessment", "work_values_assessment") VALUES ('332bf8da-a837-563d-bfb8-ce1f6795a6f7', (SELECT f.id FROM public.role_family_domains f WHERE f.role_family_id=(SELECT id FROM public.role_families WHERE code='WAT_RF08' OR name='Community Water Programme Coordinator' ORDER BY (code='WAT_RF08') DESC LIMIT 1) AND f.industry_domain_id=(SELECT x.id FROM public.industry_domains x WHERE x.industry_id=(SELECT id FROM public.industries WHERE code='IND_WAT_001' OR name='Water & Environmental Services' ORDER BY (code='IND_WAT_001') DESC LIMIT 1) AND x.domain_id=(SELECT id FROM public.domains WHERE code='WAT_D08' OR name='Community Water & Environmental Programmes' ORDER BY (code='WAT_D08') DESC LIMIT 1))), (SELECT id FROM public.role WHERE code='RMR-ROLE-08' OR name='Community Water Helper' ORDER BY (code='RMR-ROLE-08') DESC LIMIT 1), 'Helps communities understand water observations, plan informed action and communicate uncertainty clearly. Future role: Community Water Programme Coordinator; this is school-level career exploration.', 'Prepare the School-Tank Evidence Note: use the supported volume and observation records; distinguish what separation shows from what drinking-water safety would require; prepare a short note; Finish the Cost and Finding Log: multiply number of strips by unit cost, subtract expenditure from the budget, and write what the test evidence supports; Write a Fair Field-Study Proposal: specify the research question, matched variables, measurements and evidence needed; state where conclusions remain limited; Prepare the Water-Authority Handover: summarise verified observations, missing measurements, limits and the responsible next testing or referral action', 'A community water programme explains environmental observations and helps residents understand what evidence is reliable and when specialised testing is needed.', 'Explain what a school tank or separation demonstration proves and does not prove; Summarise test costs and observations in understandable language; Communicate proposed field-study steps and missing evidence; Prepare a responsible handover without declaring unsafe samples safe', 'Plain-language school-water evidence note; Community testing-cost summary; Field-study explanation; Water-authority referral and communication note; Learning modules: RMR-CAP-L01-M04 - Prepare the School-Tank Evidence Note (Core, step 1), RMR-CAP-L02-M04 - Finish the Cost and Finding Log (Important, step 2), RMR-CAP-L03-M04 - Write a Fair Field-Study Proposal (Important, step 3), RMR-CAP-L05-M05 - Prepare the Water-Authority Handover (Supporting, step 4)', 'S', 'E', 'C', 'Social work involves helping and explaining; Enterprising work coordinates local action; Conventional discipline ensures community messages accurately reflect the evidence.', 'Preferred', 'Bachelor of Social Work (BSW); B.A. Sociology; B.A. Geography; B.A. Environmental Studies', 'SEC', '{"verbal_reasoning": 92, "logical_reasoning": 78, "numerical_reasoning": 61, "data_interpretation": 80, "pattern_recognition": 68, "spatial_reasoning": 45}'::jsonb, '{"openness": 4, "conscientiousness": 4, "extraversion": 5, "agreeableness": 5, "emotional_stability": 4}'::jsonb, '{"impact": 5, "status": 2, "autonomy": 3, "security": 4, "financial": 3, "lifestyle": 4, "creativity": 4, "leadership": 5}'::jsonb, '{"areas": ["Verbal Reasoning", "Data Interpretation", "Logical Reasoning"], "rationale": "Community Water Helper uses verbal reasoning, data interpretation, logical reasoning to explain what a school tank or separation demonstration proves and does not prove, summarise test costs and observations in understandable language, and interpret source-based records. These priorities are proposed role demands, not measured learner aptitude."}'::jsonb, '{"traits": ["Agreeableness", "Extraversion", "Openness"], "rationale": "Community Water Helper benefits from agreeableness, extraversion, openness when performing summarise test costs and observations in understandable language and following through on water-authority referral and communication note. Traits guide supportive coaching, not exclusion."}'::jsonb, '{"values": ["Impact", "Leadership", "Lifestyle"], "rationale": "This pathway may reward impact, leadership, lifestyle through the work of explain what a school tank or separation demonstration proves and does not prove and producing a clear plain-language school-water evidence note. These are possible work priorities, not salary or job guarantees."}'::jsonb) ON CONFLICT (id) DO UPDATE SET "role_family_domain_id"=EXCLUDED."role_family_domain_id", "role_id"=EXCLUDED."role_id", "description"=EXCLUDED."description", "observable_behaviours"=EXCLUDED."observable_behaviours", "role_work_context"=EXCLUDED."role_work_context", "typical_work_activities"=EXCLUDED."typical_work_activities", "role_output_evidence"=EXCLUDED."role_output_evidence", "primary_riasec"=EXCLUDED."primary_riasec", "secondary_riasec"=EXCLUDED."secondary_riasec", "tertiary_riasec"=EXCLUDED."tertiary_riasec", "riasec_reason"=EXCLUDED."riasec_reason", "degree_gate"=EXCLUDED."degree_gate", "direct_degree_mapping"=EXCLUDED."direct_degree_mapping", "riasec_code_string"=EXCLUDED."riasec_code_string", "aptitude_profile"=EXCLUDED."aptitude_profile", "big_five_profile"=EXCLUDED."big_five_profile", "work_values_profile"=EXCLUDED."work_values_profile", "aptitude_assessment"=EXCLUDED."aptitude_assessment", "big5_assessment"=EXCLUDED."big5_assessment", "work_values_assessment"=EXCLUDED."work_values_assessment";
