INSERT INTO public.role_family_roles ("id", "role_family_domain_id", "role_id", "description", "observable_behaviours", "role_work_context", "typical_work_activities", "role_output_evidence", "primary_riasec", "secondary_riasec", "tertiary_riasec", "riasec_reason", "degree_gate", "direct_degree_mapping", "riasec_code_string", "aptitude_profile", "big_five_profile", "work_values_profile", "aptitude_assessment", "big5_assessment", "work_values_assessment") VALUES ('e2325fb1-a705-5ba9-82aa-2f8368312a70', (SELECT f.id FROM public.role_family_domains f WHERE f.role_family_id=(SELECT id FROM public.role_families WHERE code='WAT_RF16' OR name='Water Evidence & Policy Communication' ORDER BY (code='WAT_RF16') DESC LIMIT 1) AND f.industry_domain_id=(SELECT x.id FROM public.industry_domains x WHERE x.industry_id=(SELECT id FROM public.industries WHERE code='IND_WAT_001' OR name='Water & Environmental Services' ORDER BY (code='IND_WAT_001') DESC LIMIT 1) AND x.domain_id=(SELECT id FROM public.domains WHERE code='WAT_D16' OR name='Community Water Engagement' ORDER BY (code='WAT_D16') DESC LIMIT 1))), (SELECT id FROM public.role WHERE code='RMR-ROLE-16' OR name='Water Policy Adviser' ORDER BY (code='RMR-ROLE-16') DESC LIMIT 1), 'Explores how water decisions can be explained to communities and authorities using documented evidence and its limitations.', 'Preserve conflicting observations; explain who can approve a safety decision; identify missing information and recommend referral.', 'A community team prepares clear evidence for decision-makers but cannot independently certify drinking-water safety.', 'Review the Cup B conflict; prepare a fair field-study recommendation; interpret an incomplete test report; draft water-authority handover.', 'Discrepancy note; investigation recommendation; incomplete-test summary; authority handover.', 'S', 'E', 'I', 'Exploratory role context uses the ordered RIASEC profile SEI: the course-linked work involves review the cup b conflict; prepare a fair field-study recommendation; interpret an incomplete test report; draft water-authority handover. The mapping is provisional until career-domain review.', 'Preferred', 'B.A. Political Science; B.A. Economics; B.A. Geography; Bachelor of Social Work (BSW)', 'SEI', '{"verbal_reasoning": 92, "logical_reasoning": 78, "numerical_reasoning": 61, "data_interpretation": 80, "pattern_recognition": 68, "spatial_reasoning": 45}'::jsonb, '{"openness": 4, "conscientiousness": 4, "extraversion": 5, "agreeableness": 5, "emotional_stability": 4}'::jsonb, '{"impact": 5, "status": 2, "autonomy": 3, "security": 4, "financial": 3, "lifestyle": 4, "creativity": 4, "leadership": 5}'::jsonb, '{"areas": ["Verbal Reasoning", "Logical Reasoning", "Data Interpretation"], "rationale": "These are suggested role-demand areas for Water Policy Adviser, based on review the cup b conflict; prepare a fair field-study recommendation; interpret an incomplete test report; draft water-authority handover. They require subject-matter review before assessment matching."}'::jsonb, '{"traits": ["Conscientiousness", "Agreeableness", "Emotional Stability"], "rationale": "These traits may support the work of Water Policy Adviser, especially preserve conflicting observations; explain who can approve a safety decision; identify missing information and recommend referral. This is a role hypothesis, not an assessment of a learner."}'::jsonb, '{"values": ["Impact", "Leadership", "Security"], "rationale": "This exploratory pathway may appeal to learners who value impact, leadership, security. Individual interest must come from the learner''s assessment, not the course."}'::jsonb) ON CONFLICT (id) DO UPDATE SET "role_family_domain_id"=EXCLUDED."role_family_domain_id", "role_id"=EXCLUDED."role_id", "description"=EXCLUDED."description", "observable_behaviours"=EXCLUDED."observable_behaviours", "role_work_context"=EXCLUDED."role_work_context", "typical_work_activities"=EXCLUDED."typical_work_activities", "role_output_evidence"=EXCLUDED."role_output_evidence", "primary_riasec"=EXCLUDED."primary_riasec", "secondary_riasec"=EXCLUDED."secondary_riasec", "tertiary_riasec"=EXCLUDED."tertiary_riasec", "riasec_reason"=EXCLUDED."riasec_reason", "degree_gate"=EXCLUDED."degree_gate", "direct_degree_mapping"=EXCLUDED."direct_degree_mapping", "riasec_code_string"=EXCLUDED."riasec_code_string", "aptitude_profile"=EXCLUDED."aptitude_profile", "big_five_profile"=EXCLUDED."big_five_profile", "work_values_profile"=EXCLUDED."work_values_profile", "aptitude_assessment"=EXCLUDED."aptitude_assessment", "big5_assessment"=EXCLUDED."big5_assessment", "work_values_assessment"=EXCLUDED."work_values_assessment";
